// Layout of what a pane shows in place of its content (centered).
const (
	emptyTop  float32 = 96  // from the pane's top
	emptyMark float32 = 64  // its round icon
	emptyW    float32 = 440 // its sentence's width, at most
)

// windowGlyph parses a window button's glyph: Windows 11's, 10 points with
// lines of one.
func windowGlyph(inner string) *ui.SVG {
	return ui.MustParseSVG([]byte(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 10 10" fill="none" stroke="currentColor" stroke-width="1">` + inner + `</svg>`))
}

// The window buttons the view draws on Windows (windowButtons).
var (
	winMinimize = windowGlyph(`<path d="M0 5h10"/>`)
	winMaximize = windowGlyph(`<rect x=".5" y=".5" width="9" height="9"/>`)
	winRestore  = windowGlyph(`<path d="M2.5 2.5V.5h7v7h-2"/><rect x=".5" y="2.5" width="7" height="7"/>`)
	winClose    = windowGlyph(`<path d="M0 0l10 10M10 0 0 10"/>`)
)
